# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorDetails {
  error: Error;
  errorInfo: ErrorInfo;
  timestamp: Date;
  componentStack: string;
}

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
  onError?: (details: ErrorDetails) => void;
  resetKeys?: unknown[];           // reset boundary when these values change
  isolate?: boolean;               // wrap in its own visual container
}

interface ErrorBoundaryState {
  hasError: boolean;
  errorDetails: ErrorDetails | null;
  retryCount: number;
}

export interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  retryCount: number;
  resetError: () => void;
}

// ─── Logger ───────────────────────────────────────────────────────────────────

function logError(details: ErrorDetails, retryCount: number): void {
  const { error, errorInfo, timestamp } = details;

  console.group(
    `%c⚠ React Error Boundary [${timestamp.toISOString()}]`,
    "color: #ff4d4f; font-weight: bold; font-size: 14px;"
  );
  console.error("Error:", error.message);
  console.error("Stack:", error.stack);
  console.error("Component Stack:", errorInfo.componentStack);
  console.info("Retry attempt:", retryCount);
  console.groupEnd();

  // Example: send to an external service
  // reportToSentry({ error, errorInfo, retryCount });
}

// ─── Default Fallback UI ──────────────────────────────────────────────────────

function DefaultFallback({ error, retryCount, resetError }: FallbackProps) {
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div role="alert" style={styles.container}>
      <div style={styles.card}>
        {/* Icon */}
        <div style={styles.iconWrapper}>
          <svg
            width="48"
            height="48"
            viewBox="0 0 24 24"
            fill="none"
            stroke="#ff4d4f"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <circle cx="12" cy="12" r="10" />
            <line x1="12" y1="8" x2="12" y2="12" />
            <line x1="12" y1="16" x2="12.01" y2="16" />
          </svg>
        </div>

        {/* Heading */}
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.subtext}>
          An unexpected error occurred. You can try again or contact support if
          the problem persists.
        </p>

        {/* Retry info */}
        {retryCount > 0 && (
          <p style={styles.retryBadge}>
            Retry attempt: {retryCount}
          </p>
        )}

        {/* Actions */}
        <div style={styles.actions}>
          <button onClick={resetError} style={styles.primaryButton}>
            ↺ Try Again
          </button>
          <button
            onClick={() => window.location.reload()}
            style={styles.secondaryButton}
          >
            ⟳ Reload Page
          </button>
        </div>

        {/* Collapsible error details */}
        <button
          onClick={() => setShowDetails((v) => !v)}
          style={styles.detailsToggle}
          aria-expanded={showDetails}
        >
          {showDetails ? "▲ Hide" : "▼ Show"} error details
        </button>

        {showDetails && (
          <pre style={styles.errorDetails}>
            <strong>Message:</strong> {error.message}
            {"\n\n"}
            <strong>Stack:</strong>
            {"\n"}
            {error.stack}
          </pre>
        )}
      </div>
    </div>
  );
}

// ─── Error Boundary Class ─────────────────────────────────────────────────────

export class ErrorBoundary extends Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  static defaultProps: Partial<ErrorBoundaryProps> = {
    isolate: false,
    resetKeys: [],
  };

  state: ErrorBoundaryState = {
    hasError: false,
    errorDetails: null,
    retryCount: 0,
  };

  // ── Lifecycle ──────────────────────────────────────────────────────────────

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    // Update state so the next render shows the fallback UI.
    // errorInfo is not available here; it arrives in componentDidCatch.
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const details: ErrorDetails = {
      error,
      errorInfo,
      timestamp: new Date(),
      componentStack: errorInfo.componentStack ?? "",
    };

    this.setState({ errorDetails: details });
    logError(details, this.state.retryCount);
    this.props.onError?.(details);
  }

  componentDidUpdate(prevProps: ErrorBoundaryProps): void {
    const { resetKeys } = this.props;
    const { hasError } = this.state;

    if (
      hasError &&
      resetKeys &&
      prevProps.resetKeys &&
      resetKeys.some((key, i) => key !== prevProps.resetKeys![i])
    ) {
      this.resetError();
    }
  }

  // ── Helpers ────────────────────────────────────────────────────────────────

  resetError = (): void => {
    this.setState((prev) => ({
      hasError: false,
      errorDetails: null,
      retryCount: prev.retryCount + 1,
    }));
  };

  // ── Render ─────────────────────────────────────────────────────────────────

  render(): ReactNode {
    const { hasError, errorDetails, retryCount } = this.state;
    const { children, fallback, isolate } = this.props;

    if (hasError && errorDetails) {
      const fallbackProps: FallbackProps = {
        error: errorDetails.error,
        errorInfo: errorDetails.errorInfo,
        retryCount,
        resetError: this.resetError,
      };

      const ui = fallback ? fallback(fallbackProps) : <DefaultFallback {...fallbackProps} />;

      return isolate ? <div style={styles.isolateWrapper}>{ui}</div> : ui;
    }

    return children;
  }
}

// ─── Convenience Hook Wrapper ─────────────────────────────────────────────────

interface WithErrorBoundaryOptions extends Omit<ErrorBoundaryProps, "children"> {}

export function withErrorBoundary<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  options: WithErrorBoundaryOptions = {}
): React.FC<P> {
  const displayName =
    WrappedComponent.displayName ?? WrappedComponent.name ?? "Component";

  const WithBoundary: React.FC<P> = (props) => (
    <ErrorBoundary {...options}>
      <WrappedComponent {...props} />
    </ErrorBoundary>
  );

  WithBoundary.displayName = `withErrorBoundary(${displayName})`;
  return WithBoundary;
}

// ─── Styles ───────────────────────────────────────────────────────────────────

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "100vh",
    padding: "24px",
    backgroundColor: "#f5f5f5",
    fontFamily: "system-ui, -apple-system, sans-serif",
  },
  card: {
    background: "#ffffff",
    borderRadius: "12px",
    boxShadow: "0 4px 24px rgba(0,0,0,0.10)",
    padding: "40px 32px",
    maxWidth: "520px",
    width: "100%",
    textAlign: "center",
  },
  iconWrapper: {
    marginBottom: "16px",
  },
  heading: {
    fontSize: "22px",
    fontWeight: 700,
    color: "#1a1a1a",
    margin: "0 0 8px",
  },
  subtext: {
    fontSize: "15px",
    color: "#666",
    margin: "0 0 20px",
    lineHeight: 1.6,
  },
  retryBadge: {
    display: "inline-block",
    background: "#fff7e6",
    color: "#d46b08",
    border: "1px solid #ffd591",
    borderRadius: "20px",
    padding: "4px 14px",
    fontSize: "13px",
    marginBottom: "16px",
  },
  actions: {
    display: "flex",
    gap: "12px",
    justifyContent: "center",
    marginBottom: "20px",
    flexWrap: "wrap",
  },
  primaryButton: {
    background: "#1677ff",
    color: "#fff",
    border: "none",
    borderRadius: "8px",
    padding: "10px 24px",
    fontSize: "15px",
    fontWeight: 600,
    cursor: "pointer",
    transition: "background 0.2s",
  },
  secondaryButton: {
    background: "transparent",
    color: "#1677ff",
    border: "2px solid #1677ff",
    borderRadius: "8px",
    padding: "10px 24px",
    fontSize: "15px",
    fontWeight: 600,
    cursor: "pointer",
    transition: "all 0.2s",
  },
  detailsToggle: {
    background: "none",
    border: "none",
    color: "#999",
    fontSize: "13px",
    cursor: "pointer",
    textDecoration: "underline",
    padding: "4px",
  },
  errorDetails: {
    marginTop: "16px",
    background: "#1a1a1a",
    color: "#f0f0f0",
    borderRadius: "8px",
    padding: "16px",
    fontSize: "12px",
    textAlign: "left",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
    maxHeight: "200px",
    overflowY: "auto",
  },
  isolateWrapper: {
    border: "2px dashed #ff4d4f",
    borderRadius: "8px",
    padding: "8px",
  },
};
```

