## Usage Examples

```tsx
// App.tsx
import { ErrorBoundary, withErrorBoundary } from "./ErrorBoundary";

// ── 1. Basic wrapping ──────────────────────────────────────────────────────────
function App() {
  return (
    <ErrorBoundary>
      <MyPage />
    </ErrorBoundary>
  );
}

// ── 2. Custom fallback UI ──────────────────────────────────────────────────────
function App() {
  return (
    <ErrorBoundary
      fallback={({ error, resetError, retryCount }) => (
        <div style={{ padding: 24, color: "red" }}>
          <p>Custom error: {error.message}</p>
          <button onClick={resetError}>Retry ({retryCount})</button>
        </div>
      )}
    >
      <MyPage />
    </ErrorBoundary>
  );
}

// ── 3. Error reporting callback ────────────────────────────────────────────────
function App() {
  return (
    <ErrorBoundary
      onError={({ error, errorInfo, timestamp }) => {
        fetch("/api/log-error", {
          method: "POST",
          body: JSON.stringify({
            message: error.message,
            stack: error.stack,
            componentStack: errorInfo.componentStack,
            timestamp,
          }),
        });
      }}
    >
      <MyPage />
    </ErrorBoundary>
  );
}

// ── 4. Auto-reset when route changes (resetKeys) ───────────────────────────────
import { useLocation } from "react-router-dom";

function App() {
  const location = useLocation();
  return (
    <ErrorBoundary resetKeys={[location.pathname]}>
      <Routes />
    </ErrorBoundary>
  );
}

// ── 5. Isolated widget boundary ────────────────────────────────────────────────
function Dashboard() {
  return (
    <div>
      <ErrorBoundary isolate>
        <WeatherWidget />
      </ErrorBoundary>
      <ErrorBoundary isolate>
        <StockWidget />
      </ErrorBoundary>
    </div>
  );
}

// ── 6. HOC pattern ────────────────────────────────────────────────────────────
const SafeChart = withErrorBoundary(Chart, {
  isolate: true,
  onError: ({ error }) => console.error("Chart failed:", error),
});
```

---

## Key Design Decisions

| Feature | Approach |
|---|---|
| **Error capture** | `getDerivedStateFromError` triggers re-render; `componentDidCatch` captures full `ErrorInfo` |
| **Retry** | Increments `retryCount`, resets state — children remount cleanly |
| **Auto-reset** | `componentDidUpdate` watches `resetKeys` prop (e.g. route changes) |
| **Logging** | Structured `console.group` with timestamp; pluggable `onError` callback for Sentry/Datadog |
| **Custom UI** | Render-prop `fallback` for full control; `DefaultFallback` used otherwise |
| **Isolation** | `isolate` prop adds a visual dashed border so one broken widget doesn't hide others |
| **HOC** | `withErrorBoundary` for wrapping third-party or class components |
